		private void SetupSealData(global::Dpr.UI.CapsuleInfo capsuleInfo) {
			currentCapsuleInfo = capsuleInfo;
			sealTemplateInfos.Clear();

			AffixSealData[] affixSealDatas = capsuleInfo.Data.AffixSealDatas;
			for (int i = 0; i < capsuleInfo.Data.AffixSealCount; i++)
			{
				AffixSealData data = affixSealDatas[i];
				if (data.SealId == 0)
					continue;

				SealTemplateInfo info = sealTemplateInfos.Find(x => x.SealId == data.SealId);
				if (info == null)
				{
					info = new SealTemplateInfo();
					info.SealId = data.SealId;
					sealTemplateInfos.Add(info);
				}
				info.Count++;
			}

			sealTemplateInfos.Sort((x, y) => x.SealId.CompareTo(y.SealId));
		}
